// Create application menu
function createMenu() {
  const template = [
    {
      label: 'File',
      submenu: [
        {
          label: 'Exit',
          accelerator: 'CmdOrCtrl+Q',
          click: () => {
            app.quit();
          },
        },
      ],
    },
    {
      label: 'Edit',
      submenu: [
        { role: 'undo' },
        { role: 'redo' },
        { type: 'separator' },
        { role: 'cut' },
        { role: 'copy' },
        { role: 'paste' },
        { role: 'delete' },
        { type: 'separator' },
        { role: 'selectAll' },
      ],
    },
    {
      label: 'View',
      submenu: [
        { role: 'reload' },
        { role: 'forceReload' },
        { role: 'toggleDevTools' },
        { type: 'separator' },
        { role: 'resetZoom' },
        { role: 'zoomIn' },
        { role: 'zoomOut' },
        { type: 'separator' },
        { role: 'togglefullscreen' },
      ],
    },
    {
      label: 'Window',
      submenu: [
        { role: 'minimize' },
        { role: 'zoom' },
        { role: 'close' },
      ],
    },
  ];

  const menu = Menu.buildFromTemplate(template as any);
  Menu.setApplicationMenu(menu);
}

// App ready event
app.whenReady().then(() => {
  createMainWindow();

  // Re-create window on activation (macOS)
  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) {
      createMainWindow();
    }
  });

  // Set up IPC handlers
  setupIpcHandlers();
});

// Quit when all windows are closed (except on macOS)
app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') {
    app.quit();
  }
});

// Set up IPC handlers
function setupIpcHandlers() {
  // App info
  ipcMain.handle('app:getVersion', () => app.getVersion());
  ipcMain.handle('app:getPath', (_, name) => app.getPath(name as any));

  // Window controls
  ipcMain.handle('window:minimize', () => mainWindow?.minimize());
  ipcMain.handle('window:maximize', () => {
    if (mainWindow?.isMaximized()) {
      mainWindow.unmaximize();
    } else {
      mainWindow?.maximize();
    }
  });
  ipcMain.handle('window:close', () => mainWindow?.close());

  ipcMain.handle('window:openUrl', (_event, url: string) => {
    const child = new BrowserWindow({
      width: 1200,
      height: 800,
      show: true,
      icon: windowIcon,
      webPreferences: {
        nodeIntegration: false,
        contextIsolation: true,
        preload: path.join(__dirname, '../preload/index.js'),
        spellcheck: false,
        devTools: isDev,
      },
    });
    child.loadURL(url);
  });

  // Admin API
  ipcMain.handle('admin:getUsers', async () => {
    // TODO: Implement API call to backend
    return { success: true, data: [] };
  });

  ipcMain.handle('admin:createUser', async (_, userData) => {
    // TODO: Implement API call to backend
    return { success: true, data: userData };
  });

  // Proxy API
  ipcMain.handle('proxy:getProxies', async () => {
    // TODO: Implement API call to backend
    return { success: true, data: [] };
  });

  ipcMain.handle('proxy:testProxy', async (_, proxyId) => {
    // TODO: Implement API call to backend
    return { success: true, data: { status: 'success', latency: 120 } };
  });

  // System API
  ipcMain.handle('system:getStats', async () => {
    // TODO: Implement API call to backend
    return { success: true, data: { users: 0, proxies: 0, sessions: 0 } };
  });

  ipcMain.handle('system:getHealth', async () => {
    // TODO: Implement API call to backend
    return { success: true, data: { status: 'healthy' } };
  });
}

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
});
